3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	import java.util.Set;
8	import java.util.stream.Collectors;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's customerCode as {@code <REGION>-<HASH8>}: REGION is the region code
16	 * derived from the postcode (see {@link CityLocality}) and HASH8 is the first eight
17	 * upper-case hex characters of SHA-256 over the normalized telephone followed by the last
18	 * name. On a collision with an existing owner's code, {@code -<n>} (smallest n of 2 or more)
19	 * is appended so distinct owners always get distinct codes.
20	 */
21	public class AssignCustomerCode {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String region = CityLocality.of(owner.getCity(), owner.getPostcode());
25	        String base = region + "-" + hash8(owner.getTelephone() + owner.getLastName());
26	        Set<String> taken = ownerRepository.findAll().stream()
27	                .map(Owner::getCustomerCode).collect(Collectors.toSet());
28	        String code = base;
29	        for (int n = 2; taken.contains(code); n++) {
30	            code = base + "-" + n;
31	        }
32	        owner.setCustomerCode(code);
33	    }
34	
35	    private static String hash8(String value) {
36	        try {
37	            byte[] digest = MessageDigest.getInstance("SHA-256")
38	                    .digest(value.getBytes(StandardCharsets.UTF_8));
39	            return HexFormat.of().formatHex(digest).substring(0, 8).toUpperCase();
40	        }
41	        catch (NoSuchAlgorithmException ex) {
42	            throw new IllegalStateException(ex);
43	        }
44	    }
45	}
