12	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
13	            throws FutureRegistrationDateException {
14	        Owner owner = ownerMapper.toOwner(request);
15	        java.time.LocalDate supplied = owner.getRegistrationDate();
16	        if (supplied != null && supplied.isAfter(java.time.LocalDate.now())) {
17	            throw new FutureRegistrationDateException(supplied);
